  --kerykeion-chart-color-fire-percentage: var(--kerykeion-color-accent);
  --kerykeion-chart-color-water-percentage: var(--kerykeion-color-secondary);

  /* Aspects */
  --kerykeion-chart-color-lunar-phase-0: var(--kerykeion-color-black);
